INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (1,'sacred-geography-kaveri','Essay','The Sacred Geography of the Kaveri','5 min read','story-kaveri.jpg','srirangam','Every river in India is a goddess, but the Kaveri is also an argument — about water, about empire, and about why the greatest temples of the south stand exactly where they do.','<p>Follow the Kaveri east from Talakaveri and you follow, almost exactly, the axis of South Indian sacred history. At Srirangapatna the river splits around Tipu’s island fortress; at Srirangam it splits again around the largest temple city on earth; and from Kumbakonam to the sea it threads a delta where a Chola temple rises, on average, every few kilometres.</p><p>This is not coincidence. The Kaveri delta was the rice bowl that paid for the vimanas of Thanjavur, Gangaikonda Cholapuram and Darasuram. The Chola kings understood what every river civilisation learns: control the water and you can afford eternity. Their irrigation anicuts — some still functioning after a thousand years — and their temples are two faces of the same administration.</p><p>At Srirangam the relationship is literal. The temple’s seven enclosures occupy an island between the Kaveri and her distributary, the Kollidam, so that the pilgrim crosses water twice to reach the god. The river is the first prakaram.</p><p>Stand on the bridge at dawn and the logic of the whole landscape announces itself: water, rice, temple, town. The sacred geography of the Kaveri is not mysticism layered over economics. It is economics, remembered as worship.</p>','chola-country',NULL,0,'published','2026-08-13 01:48:00',NULL,NULL,NULL,'[]','[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (2,'night-in-konya','Field Notes','A Night in Konya','6 min read','story-konya.jpg','konya','The green dome is lit until late. Under it, in a city that has been praying in one form or another for three thousand years, Rumi still receives visitors after dark.','["I reached the Mevlana Museum at blue hour, when the tour buses have gone and the courtyard belongs to cats and old men feeding them. The fluted turquoise dome above Rumi''s tomb — the kubbe-i hadra, the Green Dome — holds the light longer than anything else in the city, as if reluctant to let the day end.", "Inside, the atmosphere is not museum but shrine. Visitors weep quietly before the great sarcophagus with its enormous turban. A guard who had worked there thirty years told me the evening shift was the one everyone wanted: \\"In the day they photograph. At night they talk to him.\\"", "Konya rewards the night wanderer. The Seljuk portals of the İnce Minare madrasa are floodlit against the dark; the Alaeddin hill, oldest ground in the city, fills with families drinking tea. Nowhere in Turkey does the thirteenth century feel so casually present.", "I walked back past the museum near midnight. The dome was still lit. It is lit every night. Some cities keep a light on for their dead; Konya keeps one for a man who wrote that death is only the wedding night — the Şeb-i Arus — and eight centuries later the whole city still attends."]','silk-route-letters','{"body":["சுற்றுலாப் பேருந்துகள் சென்ற பின், முற்றம் பூனைகளுக்கும் அவற்றுக்கு உணவிடும் வயதானவர்களுக்கும் சொந்தமாகும் நீல நேரத்தில் மெவ்லானா அருங்காட்சியகத்தை அடைந்தேன். ரூமியின் கல்லறைக்கு மேலுள்ள குழல்வடிவ பர்கீசு நிறக் குவிமாடம் — குப்பே-இ ஹத்ரா, பச்சைக் குவிமாடம் — நகரில் வேறெதையும் விட நீளமாக ஒளியைப் பிடித்து வைக்கிறது; நாள் முடிவதை விட்டுவிட விரும்பாதவனைப் போல.","உள்ளே சூழ்நிலை அருங்காட்சியகம் அல்ல — திருத்தலம். பிரமாண்ட தலைப்பாகை அணிந்த பெரிய பெட்டிக்கல்லறைக்கு முன் வருவோர் அமைதியாக அழுகிறார்கள். மூப்பது ஆண்டுகள் அங்கு பணியாற்றிய காவலர் ஒருவர், இரவு ஷிஃப்ட்தான் எல்லோருக்கும் விருப்பமானது என்றார்: \\"பகலில் அவர்கள் படம் பிடிக்கிறார்கள். இரவில் அவருடன் பேசுகிறார்கள்.\\"","கொன்யா இரவில் உலவுபவனுக்கு வெகுமதி தருகிறது. இன்செ மினாரே மதரசாவின் செல்யுக் நுழைவாயில்கள் இருட்டில் வெளிச்சமூட்டப்பட்டு நிற்கின்றன; நகரின் பழமையான தரையான அலாயெத்தின் மலை தேநீர் குடிக்கும் குடும்பங்களால் நிரம்புகிறது. துருக்கியில் வேறெங்கும் பதின்மூன்றாம் நூற்றாண்டு இவ்வளவு சாதாரணமாக நடமாடுவதில்லை.","நள்ளிரவுக்கு அருகில் அருங்காட்சியகத்தைக் கடந்து நடந்து திரும்பினேன். குவிமாடம் இன்னும் ஒளிர்ந்தது. ஒவ்வொரு இரவும் ஒளிர்கிறது. சில நகரங்கள் தம் இறந்தவர்களுக்காக விளக்கேற்றி வைக்கின்றன; கொன்யா, மரணம் திருமண இரவு மட்டுமே — ஷெப்-இ அரூஸ் — என எழுதிய மனிதனுக்காக விளக்கேற்றுகிறது; எண்ணூறு ஆண்டுகளுக்குப் பின்னும் நகரமே அந்தத் திருமணத்திற்கு வருகிறது."],"lede":"பச்சைக் குவிமாடம் இரவுவரை ஒளிர்கிறது. மூவாயிரம் ஆண்டுகளாக ஏதேனும் ஒரு வடிவில் ஜெபித்துக் கொண்டிருக்கும் நகரில், அதன் கீழ் ரூமி இரவுக்குப் பின்னும் விருந்தினர்களை வரவேற்கிறார்.","time":"6 நிமிட வாசிப்பு","title":"கொன்யாவில் ஓர் இரவு"}',1,'published','2026-08-13 01:28:47',NULL,NULL,NULL,'[]','[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (3,'last-sculptor-mamallapuram','History','The Last Sculptor of Mamallapuram','7 min read','story-sculptor.jpg','mamallapuram','In a shed behind the Five Rathas, a man whose family has carved stone for forty generations explains why the chisel has not changed in thirteen hundred years.','["The sound reaches you before the street does: tick-tick-tick, a dozen workshops keeping slightly different time. Mamallapuram has heard this sound continuously since the Pallava king Narasimhavarman first set masons against the granite boulders in the 630s CE.", "The Sthapathis — hereditary temple sculptors — still train the old way: years of drawing before stone, years of rough work before finishing, the proportions of the god memorised from the Shilpa Shastra rather than measured. \\"The measurements are in the hand,\\" one master told me, holding up a palm calloused like the rock he works.", "What has changed is the market. The Pallavas ordered temples; today''s orders are garden Ganeshas and export Natarajas. The great commissions — a gopuram restored, a new temple in the old style — come rarely now, and each one empties the town of its best hands for years.", "He calls himself the last sculptor the way fishermen call themselves the last fishermen — partly complaint, partly boast. His son, home from an engineering degree, was finishing a small Nandi in the corner of the shed. The chisel in the boy''s hand, the father pointed out, was his grandfather''s. The sound of Mamallapuram goes on."]','stone-and-chisel','{"body":["தெருவைவிட ஒலி முன்னரே உங்களை அடைகிறது: டிக்-டிக்-டிக் — ஒரு டஜன் பட்டறைகள் சற்று வேறுபட்ட தாளத்தில். கி.பி. 630-களில் பல்லவர் மன்னர் நரசிம்மவர்மன் பளிங்குப் பாறைகள் மீது கல்தச்சர்களை ஏவியதில் இருந்து இஒலியை மாமல்லபுரம் தொடர்ந்து கேட்டு வருகிறது.","ஸ்தபதிகள் — வம்சாவழி கோயில் சிற்பிகள் — இன்றும் பழைய முறையில் பயிற்சி பெறுகிறார்கள்: கல்லுக்கு முன் ஆண்டுகள் வரைதல்; முடிச்செதுக்கலுக்கு முன் ஆண்டுகள் கரடு வேலை; தெய்வத்தின் அளவுகோல்கள் அளவிடப்படாமல் சில்ப சாஸ்திரத்திலிருந்து மனனம் செய்யப்படுகின்றன. \\"அளவுகள் கையில் உள்ளன\\" என்றார் ஒரு மாஸ்தர் — தான் வேலை செய்யும் பாறை போலவே தடித்த தன் உள்ளங்கையை உயர்த்திக் காட்டி.","மாறியிருப்பது சந்தை. பல்லவர் கோயில்களை ஆர்டர் செய்தார்கள்; இன்றைய ஆர்டர்கள் தோட்ட விநாயகர்களும் ஏற்றுமதி நடராஜர்களும். பெரிய ஆணைகள் — புதுப்பிக்கப்படும் கோபுரம், பழைய பாணியில் புதிய கோயில் — இப்போது அரிதில் வருகின்றன; ஒவ்வொன்றும் ஆண்டுகளுக்கு நகரின் சிறந்த கைகளை வெறிதாக்குகிறது.","மீனவர்கள் தங்களைக் கடைசி மீனவர்கள் என அழைப்பதுபோல அவர் தன்னைக் கடைசி சிற்பி என்கிறார் — பாதி புகார், பாதி பெருமை. பொறியியல் பட்டத்துடன் வீடு திரும்பிய அவரது மகன், கொட்டகை மூலையில் சிறிய நந்தியை முடித்துக் கொண்டிருந்தான். சிறுவனின் கையிலிருந்த சுத்தியல் அவரது பாட்டனுடையது என தந்தை சுட்டிக்காட்டினார். மாமல்லபுரத்தின் ஒலி தொடர்கிறது."],"lede":"பஞ்ச ரதங்களுக்குப் பின்னுள்ள கொட்டகையில், நாற்பது தலைமுறைகளாகக் கல் செதுக்கும் குடும்பத்தைச் சேர்ந்த ஒருவர், பதின்மூன்று நூற்றாண்டுகளாகச் சுத்தியல் ஏன் மாறவில்லை என விளக்குகிறார்.","time":"7 நிமிட வாசிப்பு","title":"மாமல்லபுரத்தின் கடைசி சிற்பி"}',2,'published',NULL,NULL,NULL,NULL,'[]','[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (4,'kyoto-in-winter','Photo Essay','Kyoto in Winter','4 min read','story-kyoto.jpg','kyoto','Snow subtracts the crowds and the colour, and what remains of Kyoto is its skeleton: rooflines, stone, incense, and the sound water makes in temple gardens.','["The Yasaka pagoda under fresh snow, photographed from the lane at Ninenzaka before seven in the morning, is the Kyoto of the postcards — except that in winter you can have it alone.", "At Ryōan-ji the fifteen stones of the karesansui garden sit in a field of white instead of raked gravel, and the garden finally shows you what it was always about: not the stones, but the space the stones are keeping.", "The crowds return by ten. The trick of winter Kyoto is simply to live by temple time — out at dawn, back for the long lunch, out again for the last hour when the light goes the colour of old gold on the wet eaves.", "What the season gives back is silence. In Gion at dusk you can hear a geiko''s footsteps on stone a street away. In summer this city is a beautiful machine for tourism. In winter it is a twelfth-century capital that happens to have electricity."]','japanese-days','{"body":["காலை ஏழுக்கு முன் நினென்சாகா சந்திலிருந்து படம்பிடிக்கப்படும் புதுப் பனியில் யசாகா பகோடா — அஞ்சல் அட்டைகளின் கியோட்டோதான்; வேறுபாடு என்னவென்றால், குளிர்காலத்தில் அதைத் தனியாக வைத்திருக்கலாம்.","ரியோன்-ஜியில், கரெசன்சுயி தோட்டத்தின் பதினைந்து கற்கள் சரளைக்குப் பதிலாக வெண்மை வயலில் அமர்கின்றன; தோட்டம் எப்போதும் சொல்ல வந்ததை இப்போது காட்டுகிறது: கற்கள் அல்ல, கற்கள் காத்து வைக்கும் இடைவெளிதான் கரு.","பத்து மணிக்குள் கூட்டம் திரும்புகிறது. குளிர்காலக் கியோட்டோவின் தந்திரம் வெறுமனே கோயில் நேரப்படி வாழ்வதுதான் — விடியற்காலையில் வெளியே, நீண்ட மதிய உணவுக்கு உள்ளே, ஈரப்பட்ட முன்கூரைகளில் ஒளி பழைய தங்க நிறமாகும் கடைசி மணி நேரத்திற்கு மீண்டும் வெளியே.","பருவம் திருப்பித் தருவது அமைதி. பொழுதுபோகும் கியோனில், ஒரு தெரு தள்ளி கெய்கோவின் காலடி ஒலியைக் கல்லின் மேல் கேட்கலாம். கோடையில் இந்நகரம் சுற்றுலாவிற்கான அழகிய இயந்திரம். குளிர்காலத்தில், மின்சாரம் நிறைந்த ஒரு பன்னிரண்டாம் நூற்றாண்டுத் தலைநகர்."],"lede":"பனி கூட்டத்தையும் நிறத்தையும் கழட்டிவிடுகிறது; கியோட்டோவில் மீதமிருப்பது அதன் எலும்புக்கூடு: கூரைக் கோடுகள், கல், தூபம், கோயில் தோட்டங்களில் நீர் எழுப்பும் ஒலி.","time":"4 நிமிட வாசிப்பு","title":"குளிர்காலத்தில் கியோட்டோ"}',3,'published',NULL,NULL,NULL,NULL,'[]','[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (5,'conversations-silk-route','People','Conversations from the Silk Route','6 min read','story-silkroute.jpg','konya','In the chaikhanas of Bukhara, Samarkand and Konya, the Silk Road is not a history lesson. It is the old man at the next table insisting you drink one more tea.','["The Silk Road survives in Uzbekistan not in the restored madrasas — magnificent as they are — but in the chaikhana, the tea house, which is still organised exactly as it was for the caravans: low tables, endless pots, strangers seated together because that is what travellers are for.", "In Bukhara an old silversmith named Anvar told me his family had worked the same street for eleven generations, and that the tourists had simply replaced the merchants. \\"Before, they bought knives and rode away. Now they buy knives and fly away. The street does not care.\\"", "Tea house talk runs on an old economy: information, gossip, news of the road. Within an hour of sitting down in Samarkand I knew which border crossing was slow, which shared-taxi driver overcharged, and whose daughter was marrying whose son in three cities I will never visit.", "This is the real monument of the route — not the tilework but the protocol. Two thousand years of strangers arriving dusty and leaving fed. The tea is still hot, the table is still low, and the old men still insist: one more. The road is long. Sit."]','silk-route-letters','{"body":["புதுப்பிக்கப்பட்ட மதரசாக்களில் அல்ல — அவை எவ்வளவு அற்புதமாக இருந்தாலும் — சாய்கானாவில்தான், தேநீர் வீட்டில்தான், பட்டுப் பாதை உஸ்பெகிஸ்தானில் உயிர்வாழ்கிறது; ஊர்திகளுக்காக அமைக்கப்பட்டதுபோலவே இன்றும் அமைந்திருக்கிறது: தாழ்ந்த மேசைகள், முடிவிலா குடங்கள், அந்நியர்கள் ஒன்றாக அமர்தல் — பயணிகள் அதற்காகத்தானே.","புகாராவில் அன்வார் என்ற முதிய வெள்ளிச் செதுக்குவோர், தன் குடும்பம் பதினொரு தலைமுறைகளாக அதே தெருவில் வேலை செய்து வருவதாகவும், சுற்றுலாப் பயணிகள் வெறுமனே வாணிகர்களின் இடத்தைப் பிடித்திருப்பதாகவும் சொன்னார். \\"முன்பு, கத்திகளை வாங்கிக் குதிரையில் சென்றார்கள். இப்போது கத்திகளை வாங்கி விமானத்தில் செல்கிறார்கள். தெருவிற்குக் கவலையில்லை.\\"","தேநீர் வீட்டுப் பேச்சு ஒரு பழைய பொருளாதாரத்தில் ஓடுகிறது: தகவல், வதந்தி, பாதை செய்திகள். சமர்கந்தில் அமர்ந்து ஒரு மணி நேரத்திற்குள் எந்த எல்லைக் கடவை மெதுவானது, எந்த சேர்-டாக்ஸி ஓட்டுநர் அதிகம் வசூலிக்கிறார், நான் ஒருபோதும் செல்லாத மூன்று நகரங்களில் யார் மகள் யார் மகனை மணக்கிறாள் எனத் தெரிந்துவிட்டது.","பாதையின் உண்மையான நினைவுச்சின்னம் இதுவே — ஓட்டுகள் அல்ல, ஒழுங்குமுறை. புழுதி படிந்து வந்து திருப்தியுடன் புறப்பட்ட இரண்டாயிரம் ஆண்டுகளின் அந்நியர்கள். தேநீர் இன்னும் சூடாக உள்ளது, மேசை இன்னும் தாழ்வாக உள்ளது, மூதாட்டிகள் இன்னும் வற்புறுத்துகிறார்கள்: இன்னொன்று. பாதை நீளமானது. அமருங்கள்."],"lede":"புகாரா, சமர்கந்த், கொன்யா ஆகியவற்றின் சாய்கானாக்களில், பட்டுப் பாதை வரலாற்றுப் பாடமல்ல. அடுத்த மேசையிலிருக்கும் மூதாட்டி, இன்னொரு தேநீர் குடிக்க வேண்டும் என வற்புறுத்துவதுதான் அது.","time":"6 நிமிட வாசிப்பு","title":"பட்டுப் பாதையிலிருந்து உரையாடல்கள்"}',4,'published',NULL,NULL,NULL,NULL,'[]','[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (420001,'nara-deer-at-dawn','Field Notes','Nara: Deer at Dawn','4 min read','dest-japan.jpg','nara','Before the tour buses arrive, the park belongs to the deer — and to the bell of Tōdai-ji rolling over the wet grass.','<p>Nara wakes slowly. The deer, semi-sacred messengers of the Kasuga shrine, step out of the treeline as the first light catches the bronze of the great Buddha hall.</p><p>A vendor sets out stacks of shika senbei crackers, and within minutes the morning''s negotiations begin — a bow for a biscuit, the old contract between the town and its animals.</p>','japanese-days',NULL,0,'published',NULL,NULL,NULL,NULL,'[]','[]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (420002,'riding-the-kyoto-local','People','Riding the Kyoto Local','5 min read','story-kyoto.jpg','kyoto','The slow line to Arashiyama is a moving tea room — schoolchildren, market bags, and a monk reading the sports page.','<p>Every carriage on the Randen line is a small theatre. Between the temple stops, the city shows its unguarded face.</p><p>An old woman offers me a mandarin. Outside, the bamboo groves slide past like a green curtain being drawn.</p>','japanese-days',NULL,0,'published',NULL,NULL,NULL,NULL,'[]','[]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (420003,'fuji-five-lakes-loop','Photo Essay','The Fuji Five Lakes Loop','6 min read','dest-japan.jpg','fuji-five-lakes','Five lakes, one mountain, and weather that changes its mind every hour — circling Fuji without ever quite seeing it.','<p>Kawaguchiko at dawn is a mirror; by nine the mountain has pulled its curtain of cloud across.</p><p>At Saiko the lava caves breathe cold air, and the moss forest keeps its own green counsel.</p>','japanese-days',NULL,0,'published',NULL,NULL,NULL,NULL,'[]','[]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (420004,'hiroshima-quiet-morning','Essay','Hiroshima, a Quiet Morning','5 min read','dest-japan.jpg','hiroshima','The Peace Memorial Park before the school groups arrive — a city that chose remembrance without bitterness.','<p>The A-Bomb Dome stands in the morning haze like a sentence the city refused to finish.</p><p>An old man feeds the river turtles and tells me the carp came back first, in the autumn of 1945.</p>','japanese-days',NULL,0,'published',NULL,NULL,NULL,NULL,'[]','[]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (420023,'the-coromandel-light','Photo Essay','The Coromandel Light','4 min read','story-sculptor.jpg','mamallapuram','On the coast at Mamallapuram the light arrives before the heat — a pale gold that turns the granite rathas the colour of old brass.','<p>The Shore Temple faces east for a reason. At six in the morning the sun climbs straight out of the Bay of Bengal and lays its first light on the Pallava granite.</p><p>Fishermen walk their nets past seven-century-old carvings, and for a few minutes the whole headland belongs to them alone.</p>','stone-and-chisel',NULL,0,'published',NULL,NULL,NULL,NULL,'[]','[]');
INSERT INTO `stories` (`id`,`slug`,`tag`,`title`,`readTime`,`img`,`placeSlug`,`lede`,`body`,`seriesSlug`,`ta`,`sort`,`status`,`publishedAt`,`seoTitle`,`seoDescription`,`seoKeywords`,`relatedPlaces`,`contributors`) VALUES (420024,'madurai-after-midnight','Field Notes','Madurai After Midnight','5 min read','dest-india.jpg','meenakshi','When the last puja ends and the corridors of Meenakshi empty, the temple town exhales — flower sellers counting the day''s jasmine, dosa griddles still hot at the corners.','<p>Madurai does not really sleep; it only lowers its voice. The four towers hold the moon between them.</p><p>A priest cycles home with his lamp still lit. Somewhere behind the east gopuram, a wedding party is just beginning.</p>','temple-towns',NULL,0,'published',NULL,NULL,NULL,NULL,'[]','[]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (1,'brihadisvara','Brihadisvara Temple','Thanjavur, Tamil Nadu','India','india','Heritage','hero.jpg','The Brihadisvara Temple, called Rajarajesvaram by its builder, is a Chola-era Hindu temple dedicated to Shiva on the south bank of the Kaveri. Completed in 1010 CE, it is one of the largest temples in India and a defining monument of Dravidian architecture.','[{"heading":"History","body":"<p>Rajaraja I (r. 985–1014 CE) built the temple at the height of Chola power, and the main deity was consecrated in 1010 CE — the twenty-fifth year of his reign. Inscriptions on its walls record gifts of gold, jewels, land and entire villages in remarkable administrative detail, making the temple as much a historical archive as a shrine.</p><p>The temple survived wars, the fall of the Cholas, and centuries of weather almost intact. In 1987 it was inscribed on the UNESCO World Heritage List, and in 2004 its listing was extended as part of the \\"Great Living Chola Temples\\" — living because worship has continued here, unbroken, for over a thousand years.</p>"},{"heading":"Architecture","body":"<p>The vimana (sanctum tower) rises about 66 metres in thirteen diminishing tiers, built entirely of interlocked granite without mortar. A single capstone estimated at around 80 tonnes crowns the tower — how it was raised remains one of the great engineering debates of the period.</p><p>Inside the circumambulatory passages, some of the finest surviving Chola murals depict Shiva in his various forms. The great Nandi in front of the sanctum, carved from a single rock, is among the largest in India at nearly 16 feet long.</p>"},{"heading":"Visiting","body":"<p>The temple sits at the heart of Thanjavur city and opens at dawn and again in the evening; the hour before sunset, when the granite turns the colour of burnt honey, is the one the photographers wait for. Non-Hindus may walk the courtyards and cloisters freely. Dress modestly; leather items are discouraged inside the prakaram.</p>"}]','[{"label":"Built","value":"1003–1010 CE"},{"label":"Builder","value":"Rajaraja Chola I"},{"label":"Dynasty","value":"Chola"},{"label":"Style","value":"Dravidian"},{"label":"Deity","value":"Shiva (Peruvudaiyar)"},{"label":"Vimana height","value":"≈ 66 m, 13 tiers"},{"label":"Material","value":"Granite"},{"label":"UNESCO","value":"World Heritage, 1987 / 2004"}]','["gangaikonda","airavatesvara","srirangam"]',NULL,'2026-08-13 00:30:07','2026-08-14 04:32:58','published',NULL,'Membalam Road, Thanjavur, Tamil Nadu 613001, India',10.7827,79.1316,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (2,'gangaikonda','Gangaikonda Cholapuram','Ariyalur district, Tamil Nadu','India','india','Heritage','place-gangaikonda.jpg','Gangaikonda Cholapuram — "the city of the Chola who took the Ganga" — was founded by Rajendra I around 1035 CE to commemorate his victorious northern expedition, and its Brihadisvara temple is the second of the three Great Living Chola Temples.','[{"body": ["After his armies reached the Ganges around 1023 CE, Rajendra I moved the Chola capital from Thanjavur to this new city and poured the spoils of empire into its temple. For roughly 250 years it served as the Chola seat of power."], "heading": "History"}, {"body": ["The vimana, at about 55 metres, is deliberately shorter than his father''s at Thanjavur — but more refined: its gentle concave curves give it a feminine grace that scholars read as a conscious stylistic answer to Rajaraja''s masculine massiveness. The lion-well (simhakeni), the Chandikesvara shrine and the weathered Nandi complete the complex."], "heading": "Architecture"}, {"body": ["The temple lies about 70 km northeast of Thanjavur and receives a fraction of its crowds. Come in the late afternoon; the lawns and enclosure walls make it one of the most peaceful of the great Chola sites."], "heading": "Visiting"}]','[{"label":"Built","value":"c. 1035 CE"},{"label":"Builder","value":"Rajendra Chola I"},{"label":"Dynasty","value":"Chola"},{"label":"Style","value":"Dravidian"},{"label":"Vimana height","value":"≈ 55 m"},{"label":"UNESCO","value":"World Heritage, 2004"}]','["brihadisvara","airavatesvara","srirangam"]','{"country":"இந்தியா","facts":[{"label":"கட்டப்பட்டது","value":"சுமார் கி.பி. 1035"},{"label":"கட்டியவர்","value":"முதலாம் இராசேந்திர சோழன்"},{"label":"வம்சம்","value":"சோழர்"},{"label":"பாணி","value":"திராவிடம்"},{"label":"விமான உயரம்","value":"≈ 55 மீ"},{"label":"யுனெஸ்கோ","value":"உலகப் பாரம்பரியம், 2004"}],"name":"கங்கைகொண்ட சோழபுரம்","region":"அரியலூர் மாவட்டம், தமிழ்நாடு","sections":[{"body":["கி.பி. 1023-இல் அவரது படைகள் கங்கையை அடைந்த பிறகு, இராசேந்திரன் தலைநகரை தஞ்சாவூரிலிருந்து இப்புதிய நகருக்கு மாற்றி, பேரரசின் கொள்ளைப்பொருளை இக்கோயிலில் செலுத்தினார். சுமார் 250 ஆண்டுகள் இது சோழர்களின் அரசுரிமை இருக்கையாக விளங்கியது."],"heading":"வரலாறு"},{"body":["சுமார் 55 மீட்டர் உயரமுள்ள விமானம், தஞ்சாவூரில் தந்தை கட்டியதைவிட வேண்டுமென்றே குறைவானது — ஆனால் மேலும் நுட்பமானது: அதன் மெல்லிய குழிவு வளைவுகள் பெண்மையான அழகைத் தருகின்றன; இராஜராஜனின் ஆண்மையான மாபெரும் தன்மைக்கு உணர்ந்து கொடுக்கப்பட்ட பாணிப் பதில் என அறிஞர்கள் பார்க்கிறார்கள். சிங்கக்கிணறு (சிம்மக்கேனி), சண்டிகேஸ்வரர் சன்னதி, வானிலையால் மங்கிய நந்தி ஆகியவை வளாகத்தை நிறைவு செய்கின்றன."],"heading":"கட்டிடக்கலை"},{"body":["கோயில் தஞ்சாவூரிலிருந்து வடகிழக்கே சுமார் 70 கி.மீ. தொலைவில் உள்ளது; தஞ்சாவூர் பெறும் கூட்டத்தில் சிறு பகுதியே இங்கு வருகிறது. பிற்பகலில் வாருங்கள்; புல்வெளிகளும் மதில்சுவர்களும் இதைப் பெரிய சோழர் தளங்களில் மிக அமைதியானதாக்குகின்றன."],"heading":"பார்வையிட"}],"summary":"\\"கங்கையைக் கொண்டுவந்த சோழனின் நகரம்\\" என்ற பொருள்கொண்ட கங்கைகொண்ட சோழபுரம், முதலாம் இராசேந்திரனால் அவரது வெற்றிகரமான வடநாட்டுப் படையெடுப்பை நினைவுகூரும் வகையில் கி.பி. 1035-இல் நிறுவப்பட்டது; இங்குள்ள பிருகதீஸ்வரர் கோயில் உயிரோட்டமுள்ள மூன்று பெரும் சோழர் கோயில்களில் இரண்டாவது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Gangaikonda Cholapuram, Ariyalur district, Tamil Nadu 612901, India',11.2071,79.448,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (3,'airavatesvara','Airavatesvara Temple','Darasuram, near Kumbakonam, Tamil Nadu','India','india','Heritage','place-airavatesvara.jpg','The Airavatesvara Temple at Darasuram, built by Rajaraja II in the 12th century, is the smallest and most exquisitely carved of the three Great Living Chola Temples — a jewel-box of stone where the mandapa is shaped like a chariot drawn by horses.','[{"body": ["Rajaraja II (r. 1146–1173 CE) built the temple at Darasuram, then a suburb of the Chola heartland. Its name remembers the legend of Airavata, Indra''s white elephant, who worshipped Shiva here to be released from a curse."], "heading": "History"}, {"body": ["The Rajagambhira mandapa in front is conceived as a celestial chariot, its wheels and horses carved in the round. The balustraded steps are the famous \\"musical steps\\" that are said to ring with the seven notes when struck. Pillars carry miniature panels — the 63 Nayanmar saints, dance karanas, everyday scenes — carved with a jeweller''s patience."], "heading": "Architecture"}, {"body": ["Darasuram is 4 km from Kumbakonam and pairs naturally with a day among the temple towns of the Kaveri delta. The complex is compact; an unhurried hour covers it, but the carvings reward a second loop."], "heading": "Visiting"}]','[{"label":"Built","value":"12th century CE"},{"label":"Builder","value":"Rajaraja Chola II"},{"label":"Dynasty","value":"Chola"},{"label":"Style","value":"Dravidian"},{"label":"Known for","value":"Chariot mandapa, musical steps"},{"label":"UNESCO","value":"World Heritage, 2004"}]','["brihadisvara","gangaikonda","srirangam"]','{"country":"இந்தியா","facts":[{"label":"கட்டப்பட்டது","value":"கி.பி. 12-ஆம் நூற்றாண்டு"},{"label":"கட்டியவர்","value":"இரண்டாம் ராஜராஜ சோழன்"},{"label":"வம்சம்","value":"சோழர்"},{"label":"பாணி","value":"திராவிடம்"},{"label":"புகழ்பெற்றது","value":"தேர் மண்டபம், இசைப் படிகள்"},{"label":"யுனெஸ்கோ","value":"உலகப் பாரம்பரியம், 2004"}],"name":"ஐராவதேஸ்வரர் கோயில்","region":"தாராசுரம், கும்பகோணம் அருகில், தமிழ்நாடு","sections":[{"body":["இரண்டாம் இராஜராஜன் (ஆட்சி கி.பி. 1146–1173) சோழர் பெருநகரின் புறநகரான தாராசுரத்தில் இக்கோயிலைக் கட்டினார். சாபத்திலிருந்து விடுபட இந்திரனின் வெள்ளையானை ஐராவதம் இங்கு சிவனை வணங்கிய புராணத்தை இப்பெயர் நினைவுபடுத்துகிறது."],"heading":"வரலாறு"},{"body":["முன்புள்ள இராஜகம்பீர மண்டபம் விண்ணகத் தேராகக் கற்பனை செய்யப்பட்டுள்ளது; அதன் சக்கரங்களும் குதிரைகளும் முழு உருவச் சிற்பங்களாகச் செதுக்கப்பட்டுள்ளன. முன்றில்படிகள் புகழ்பெற்ற \\"இசைப் படிகள்\\" — தட்டினால் ஏழு சுரங்கள் ஒலிக்கும் எனச் சொல்லப்படுகின்றன. தூண்களில் 63 நாயன்மார் துறவிகள், நடனக் கரணங்கள், அன்றாடக் காட்சிகள் போன்ற நுண்ணிய பலகைகள் ஒரு நகைச் செதுக்குவோனின் பொறுமையுடன் செதுக்கப்பட்டுள்ளன."],"heading":"கட்டிடக்கலை"},{"body":["தாராசுரம் கும்பகோணத்திலிருந்து 4 கி.மீ. தொலைவில் உள்ளது; காவேரி டெல்டா கோயில் நகரங்களின் ஒருநாள் பயணத்துடன் இயற்கையாக இணைகிறது. வளாகம் சிறியது; அவசரமின்றி ஒரு மணி நேரம் போதும் — ஆனால் சிற்பங்கள் மற்றொரு சுற்றுக்கு வெகுமதி தரும்."],"heading":"பார்வையிட"}],"summary":"12-ஆம் நூற்றாண்டில் இரண்டாம் இராஜராஜனால் தாராசுரத்தில் கட்டப்பட்ட ஐராவதேஸ்வரர் கோயில், உயிரோட்டமுள்ள மூன்று பெரும் சோழர் கோயில்களில் மிகச் சிறியதும் மிக நுணுக்கமாகச் செதுக்கப்பட்டதும் — குதிரைகள் இழுக்கும் தேர் வடிவ மண்டபம் கொண்ட கல்லின் நகைப்பெட்டி."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Darasuram, Kumbakonam, Tamil Nadu 612702, India',10.9487,79.3566,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (4,'meenakshi','Meenakshi Amman Temple','Madurai, Tamil Nadu','India','india','Heritage','dest-india.jpg','The Meenakshi Amman Temple is the beating heart of Madurai — a sprawling walled city-within-a-city dedicated to the fish-eyed goddess Meenakshi and her consort Sundareswarar, famous for its towering, sculpture-encrusted gopurams.','[{"body": ["Madurai''s temple is ancient — the city itself grew around it — but most of what stands today was raised under the Nayak rulers of the 16th and 17th centuries, above all Tirumala Nayak. The complex covers some 14 acres with four entrances aligned to the cardinal directions."], "heading": "History"}, {"body": ["Fourteen gopurams rise over the complex, the southern tower reaching nearly 52 metres, each encrusted with thousands of painted stucco figures of gods, demons and celestial beings. Inside, the Hall of a Thousand Pillars (Ayiram Kaal Mandapam) is a forest of sculpted granite columns, no two alike."], "heading": "Architecture"}, {"body": ["The evening ceremony, when Sundareswarar is carried in procession to Meenakshi''s shrine for the night, is one of the great daily rituals of South India. Arrive before 9 pm for the closing procession. The temple stays busy from before dawn until late night."], "heading": "Visiting"}]','[{"label":"Rebuilt","value":"16th–17th century (Nayak)"},{"label":"Deities","value":"Meenakshi & Sundareswarar"},{"label":"Gopurams","value":"14 towers"},{"label":"Style","value":"Dravidian"},{"label":"Complex area","value":"≈ 14 acres"}]','["srirangam","brihadisvara","mamallapuram"]','{"country":"இந்தியா","facts":[{"label":"மீண்டும் கட்டப்பட்டது","value":"16–17-ஆம் நூற்றாண்டு (நாயக்கர்)"},{"label":"மூலவர்கள்","value":"மீனாட்சி & சுந்தரேஸ்வரர்"},{"label":"கோபுரங்கள்","value":"14 கோபுரங்கள்"},{"label":"பாணி","value":"திராவிடம்"},{"label":"வளாகப் பரப்பு","value":"≈ 14 ஏக்கர்"}],"name":"மீனாட்சி அம்மன் கோயில்","region":"மதுரை, தமிழ்நாடு","sections":[{"body":["மதுரையின் கோயில் பண்டையது — நகரமே அதனைச் சுற்றி வளர்ந்தது — ஆனால் இன்று நிற்பவற்றில் பெரும்பாலானவை 16, 17-ஆம் நூற்றாண்டு நாயக்கர் ஆட்சியாளர்களால், முக்கியமாக திருமலை நாயக்கரால் எழுப்பப்பட்டவை. நான்கு திசைகளுக்கும் ஒத்த நுழைவுகளுடன் வளாகம் சுமார் 14 ஏக்கர் பரப்பில் பரவியுள்ளது."],"heading":"வரலாறு"},{"body":["வளாகத்தின் மேல் பதினான்கு கோபுரங்கள் எழுகின்றன; தென் கோபுரம் கிட்டத்தட்ட 52 மீட்டரை அடைகிறது. ஒவ்வொன்றிலும் தெய்வங்கள், அரக்கர்கள், வானவர்கள் என ஆயிரக்கணக்கான வண்ணச் சுதை உருவங்கள் பதித்திருக்கின்றன. உள்ளே, ஆயிரங்கால் மண்டபம் ஒன்றுக்கொன்று ஒப்பில்லாத சிற்பப் பளிங்குத் தூண்களின் காடு."],"heading":"கட்டிடக்கலை"},{"body":["சுந்தரேஸ்வரர் இரவுக்காக மீனாட்சியின் சன்னதிக்கு ஊர்வலமாக எடுத்துச் செல்லப்படும் இரவுச் சடங்கு தென்னிந்தியாவின் பெரும் அன்றாடச் சடங்குகளில் ஒன்று. மூடும் ஊர்வலத்திற்கு இரவு 9 மணிக்கு முன் வருங்கள். கோயில் அதிகாலைக்கு முன்பிருந்து இரவு வரை துடிப்புடன் இருக்கும்."],"heading":"பார்வையிட"}],"summary":"மீனாட்சி அம்மன் கோயில் மதுரையின் துடிக்கும் இதயம் — மீன்போன்ற கண்களுடைய தெய்வம் மீனாட்சிக்கும் அவரது காவலன் சுந்தரேஸ்வரருக்கும் அர்ப்பணிக்கப்பட்ட, சிற்பங்கள் படர்ந்த உயர்ந்த கோபுரங்களுக்குப் புகழ்பெற்ற, மதில்சூழ்ந்த நகருக்குள் நகரம்."}','2026-08-13 00:30:07','2026-08-13 01:03:19','published',NULL,'Madurai Main, Madurai, Tamil Nadu 625001, India',9.9195,78.1193,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (5,'mamallapuram','Mamallapuram','Chengalpattu district, Tamil Nadu','India','india','Heritage','story-sculptor.jpg','Mamallapuram, the Pallava port-city on the Bay of Bengal, is where South Indian stone architecture was effectively invented in the 7th century — its Shore Temple, monolithic rathas and the great bas-relief are UNESCO World Heritage.','[{"body": ["Under Narasimhavarman I \\"Mamalla\\" (r. 630–668 CE), from whom the town takes its name, Pallava craftsmen began cutting temples out of living rock — experiments that became the grammar of Dravidian architecture for the next thousand years. The town was also a busy port trading with Southeast Asia and Rome."], "heading": "History"}, {"body": ["The Pancha Rathas are five shrines each carved from a single boulder, unfinished at the Pallavas'' fall. The Descent of the Ganges — an enormous open-air bas-relief across two cliffs — teems with gods, ascetics, elephants and a cat performing mock penance. The Shore Temple, built a generation later in dressed stone, has watched the surf for thirteen centuries."], "heading": "Monuments"}, {"body": ["The monuments cluster within walking distance of each other, about 60 km south of Chennai. Go early for the bas-relief, end the day at the Shore Temple for sunset — and listen for the tap of chisels: the sculptors'' quarter still works stone as it did in Pallava times."], "heading": "Visiting"}]','[{"label":"Flourished","value":"7th–8th century CE"},{"label":"Dynasty","value":"Pallava"},{"label":"Key works","value":"Shore Temple, Pancha Rathas"},{"label":"UNESCO","value":"World Heritage, 1984"},{"label":"Location","value":"Bay of Bengal coast"}]','["brihadisvara","meenakshi","gangaikonda"]','{"country":"இந்தியா","facts":[{"label":"சிறந்த காலம்","value":"கி.பி. 7–8-ஆம் நூற்றாண்டு"},{"label":"வம்சம்","value":"பல்லவர்"},{"label":"முக்கியப் படைப்புகள்","value":"கடற்கரைக் கோயில், பஞ்ச ரதங்கள்"},{"label":"யுனெஸ்கோ","value":"உலகப் பாரம்பரியம், 1984"},{"label":"அமைவிடம்","value":"வங்கக் கடல் கரை"}],"name":"மாமல்லபுரம்","region":"செங்கல்பட்டு மாவட்டம், தமிழ்நாடு","sections":[{"body":["நகரம் பெயர்பெற்ற முதலாம் நரசிம்மவர்மன் \\"மாமல்லன்\\" (ஆட்சி கி.பி. 630–668) காலத்தில், பல்லவர் கைவினைஞர்கள் உயிருள்ள பாறையிலிருந்தே கோயில்களை வெட்டத் தொடங்கினர் — அடுத்த ஆயிரம் ஆண்டுகளுக்குத் திராவிடக் கட்டிடக்கலையின் இலக்கணமான சோதனைகள் அவை. தென்கிழக்கு ஆசியாவுடனும் ரோமுடனும் வாணிபம் செய்த பரபரப்பான துறைமுகமும் இந்நகரம்."],"heading":"வரலாறு"},{"body":["பஞ்ச ரதங்கள் ஒவ்வொன்றும் ஒற்றைப் பாறையிலிருந்து செதுக்கப்பட்ட ஐந்து கோயில்கள்; பல்லவர் வீழ்ச்சியில் பாதியில் நின்றவை. இரண்டு மலைச்சரிவுகள் மீது பரந்த மாபெரும் புறனிலைச் சிற்பமான கங்கை அவதரணம் — தெய்வங்கள், துறவிகள், யானைகள், பாசாங்கு தவம் செய்யும் பூனை என நிரம்பியிருக்கிறது. ஒரு தலைமுறைக்குப் பின் வெட்டப்பட்ட கல்லால் கட்டப்பட்ட கடற்கரைக் கோயில் பதின்மூன்று நூற்றாண்டுகளாக அலைகளைக் கண்டு நிற்கிறது."],"heading":"நினைவுச்சின்னங்கள்"},{"body":["சென்னையிலிருந்து தெற்கே சுமார் 60 கி.மீ. தொலைவில், நினைவுச்சின்னங்கள் நடந்து செல்லும் தூரத்தில் ஒன்றோடொன்று அணுக்கமாக உள்ளன. புறனிலைச் சிற்பத்திற்குக் காலையில் செல்லுங்கள்; சூரிய அஸ்தமனத்தைக் கடற்கரைக் கோயிலில் முடியுங்கள் — சுத்தியலின் தக்தக் ஒலியைக் கவனியுங்கள்: சிற்பிகளின் குடியிருப்பு இன்றும் பல்லவர் காலத்தைப் போலவே கல்லை வேலை செய்கிறது."],"heading":"பார்வையிட"}],"summary":"வங்கக் கடல் கரையிலுள்ள பல்லவர் துறைமுக நகரம் மாமல்லபுரம் — 7-ஆம் நூற்றாண்டில் தென்னிந்தியக் கல் கட்டிடக்கலை உண்மையில் கண்டுபிடிக்கப்பட்ட இடம்; கடற்கரைக் கோயில், ஒற்றைக்கல் ரதங்கள், மாபெரும் புறனிலைச் சிற்பம் ஆகியவை யுனெஸ்கோ உலகப் பாரம்பரியம்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Mahabalipuram, Chengalpattu district, Tamil Nadu 603104, India',12.6208,80.193,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (6,'srirangam','Srirangam','Tiruchirappalli, Tamil Nadu','India','india','Heritage','story-kaveri.jpg','Srirangam is a temple island in the Kaveri whose Sri Ranganathaswamy Temple is the largest functioning Hindu temple complex in the world — 156 acres of concentric enclosures that are, in effect, a walled sacred city.','[{"body": ["The shrine of the reclining Ranganatha is among the oldest continuously worshipped in India, praised in the earliest Tamil Sangam literature. Enlarged over centuries by the Cholas, Pandyas, Hoysalas, Vijayanagara kings and the Madurai Nayaks, it survived a 14th-century sack and was rebuilt grander still."], "heading": "History"}, {"body": ["Seven concentric prakarams wrap the sanctum; the outer enclosures contain streets, houses, shops and entire neighbourhoods. Twenty-one gopurams crown the gateways — the southern rajagopuram, completed in 1987, rises 73 metres, the second-tallest temple tower in Asia."], "heading": "Architecture"}, {"body": ["Cross the Kaveri from Tiruchirappalli at dawn and walk the seven enclosures inward as the town wakes around you. The Vaikuntha Ekadasi festival in December–January draws over a million pilgrims; ordinary mornings are the island''s gift."], "heading": "Visiting"}]','[{"label":"Deity","value":"Ranganatha (reclining Vishnu)"},{"label":"Complex area","value":"≈ 156 acres"},{"label":"Enclosures","value":"7 prakarams"},{"label":"Gopurams","value":"21"},{"label":"Rajagopuram","value":"73 m, completed 1987"}]','["brihadisvara","meenakshi","gangaikonda"]','{"country":"இந்தியா","facts":[{"label":"மூலவர்","value":"ரங்கநாதர் (பள்ளிகொண்ட விஷ்ணு)"},{"label":"வளாகப் பரப்பு","value":"≈ 156 ஏக்கர்"},{"label":"பிரகாரங்கள்","value":"7 பிரகாரங்கள்"},{"label":"கோபுரங்கள்","value":"21"},{"label":"ராஜகோபுரம்","value":"73 மீ, 1987-இல் நிறைவு"}],"name":"ஸ்ரீரங்கம்","region":"திருச்சிராப்பள்ளி, தமிழ்நாடு","sections":[{"body":["பள்ளிகொண்டிருக்கும் ரங்கநாதரின் சன்னதி இந்தியாவில் தொடர்ந்து வழிபடப்படும் பழமையான சன்னதிகளில் ஒன்று; தொடக்ககாலத் தமிழ்ச் சங்க இலக்கியத்தில் பாடப்பட்டது. நூற்றாண்டுகளாகச் சோழர், பாண்டியர், ஒய்சாலர், விசயநகர மன்னர்கள், மதுரை நாயக்கர்களால் விரிவாக்கப்பட்டது; 14-ஆம் நூற்றாண்டுச் சூறையாடலைத் தாண்டி மீண்டும் பெரிதாக எழுந்தது."],"heading":"வரலாறு"},{"body":["ஏழு ஒன்றுக்கொன்றுள் அமைந்த பிரகாரங்கள் கருவறையைச் சுற்றுகின்றன; வெளிப் பிரகாரங்களில் தெருக்கள், வீடுகள், கடைகள், குடியிருப்புகள் முழுவதும் உள்ளன. நுழைவாயில்களின் மேல் இருபத்தொரு கோபுரங்கள் — 1987-இல் நிறைவடைந்த தென் ராஜகோபுரம் 73 மீட்டர் எழுகிறது; ஆசியாவின் இரண்டாவது உயரமான கோயில் கோபுரம்."],"heading":"கட்டிடக்கலை"},{"body":["அதிகாலையில் திருச்சிராப்பள்ளியிலிருந்து காவேரியைக் கடந்து, சுற்றிலும் நகரம் விழிக்க ஏழு பிரகாரங்களையும் உள்நோக்கி நடந்து செல்லுங்கள். டிசம்பர்–ஜனவரியில் வைகுண்ட ஏகாதசி விழா பத்து இலட்சத்திற்கும் மேற்பட்ட பக்தர்களைக் கவர்கிறது; சாதாரண காலைகளே தீவின் பரிசு."],"heading":"பார்வையிட"}],"summary":"ஸ்ரீரங்கம் காவேரியிலுள்ள ஒரு கோயில் தீவு; அதன் ஸ்ரீ ரங்கநாதசுவாமி கோயில் உலகின் மிகப்பெரிய செயல்படும் இந்துக் கோயில் வளாகம் — 156 ஏக்கர் ஒன்றுக்கொன்றுள் அமைந்த பிரகாரங்கள், உண்மையில் ஒரு மதில்சூழ்ந்த புனித நகரம்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Srirangam, Tiruchirappalli, Tamil Nadu 620006, India',10.8626,78.6895,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (7,'gudimallam','Gudimallam','Chittoor district, Andhra Pradesh','India','india','Heritage','place-gudimallam.jpg','The Parasurameswara Temple at Gudimallam houses what many scholars consider the earliest known anthropomorphic Shiva linga — a standing figure carved on a pillar-like linga dated to around the 2nd–1st century BCE.','[{"body": ["Though the present modest temple is later, the linga it shelters is ancient beyond almost any other Shiva image: a two-armed figure standing on a yaksha-like crouching form, carved in deep relief on the shaft. It shows the moment when the aniconic pillar and the human-shaped god were still one idea."], "heading": "History"}, {"body": ["For students of religion, Gudimallam is a hinge-point: here the linga — abstract emblem of Shiva — carries the god''s earliest known body. Later Bactrian, Kushana and Gupta comparisons only underline how early and how singular the image is. Worship has continued around it for over two thousand years."], "heading": "Significance"}, {"body": ["The temple lies in a quiet village about 20 km from Tirupati, open morning and evening. It is small — the visit takes minutes — but standing before an image older than most of the world''s religions is not a small experience."], "heading": "Visiting"}]','[{"label":"Linga dated","value":"c. 2nd–1st century BCE"},{"label":"Deity","value":"Shiva (Parasurameswara)"},{"label":"Significance","value":"Earliest anthropomorphic Shiva linga"},{"label":"Location","value":"Near Tirupati"}]','["brihadisvara","mamallapuram","srirangam"]','{"country":"இந்தியா","facts":[{"label":"லிங்கக் காலம்","value":"கி.மு. 2–1-ஆம் நூற்றாண்டு"},{"label":"மூலவர்","value":"சிவன் (பரசுராமேஸ்வரர்)"},{"label":"முக்கியத்துவம்","value":"மிகப் பழமையான மனித உருவ சிவலிங்கம்"},{"label":"அமைவிடம்","value":"திருப்பதி அருகில்"}],"name":"குடிமல்லம்","region":"சித்தூர் மாவட்டம், ஆந்திரப் பிரதேசம்","sections":[{"body":["தற்போதைய எளிய கோயில் பிற்காலத்தியது எனினும், அது காக்கும் லிங்கம் மற்ற எந்த சிவ உருவத்தையும் விடப் பழமையானது: யட்சன் போன்ற குனிந்த உருவத்தின் மீது நிற்கும் இருகர உருவம், தண்டின் மீது ஆழ்ந்த உயர்தளச் சிற்பமாக வெட்டப்பட்டுள்ளது. சிலையற்ற தூணும் மனித வடிவத் தெய்வமும் இன்னும் ஒரே கருத்தாக இருந்த தருணத்தை இது காட்டுகிறது."],"heading":"வரலாறு"},{"body":["சமயத்தை ஆய்வோருக்குக் குடிமல்லம் ஒரு திருப்புமுனை: சிவனின் அருவச் சின்னமான லிங்கம் இங்கே தெய்வத்தின் மிகப் பழமையான உடலைச் சுமக்கிறது. பின்னர் வந்த பாக்திரிய, குஷாண, குப்த ஒப்பீடுகள் இஉருவம் எவ்வளவு பழமையானது, எவ்வளவு தனித்தது என்பதையே அடிக்கோடிட்டுக் காட்டுகின்றன. இரண்டாயிரம் ஆண்டுகளுக்கும் மேலாக அதனைச் சுற்றி வழிபாடு நடந்து வருகிறது."],"heading":"முக்கியத்துவம்"},{"body":["திருப்பதியிலிருந்து சுமார் 20 கி.மீ. தொலைவிலுள்ள அமைதியான கிராமத்தில் கோயில் உள்ளது; காலையிலும் மாலையிலும் திறக்கப்படும். சிறியது — விஜயம் நிமிடங்களே — ஆனால் உலகின் பெரும்பாலான சமயங்களைவிடப் பழமையான உருவத்திற்கு முன் நிற்பது சிறிய அனுபவமல்ல."],"heading":"பார்வையிட"}],"summary":"குடிமல்லம் பரசுராமேஸ்வரர் கோயில் பல அறிஞர்களின் பார்வையில் அறியப்பட்ட மிகப் பழமையான மனித உருவ சிவலிங்கத்தைக் காக்கிறது — கி.மு. 2–1-ஆம் நூற்றாண்டைச் சேர்ந்த தூண்போன்ற லிங்கத்தில் நிற்கும் உருவம் செதுக்கப்பட்டுள்ளது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Gudimallam, Chittoor district, Andhra Pradesh 517581, India',13.6055,79.583,'[{"bio":"Field notes, inscriptions and local history, compiled and edited by the Vazhi team.","link":"https://vazhi.world/about","name":"Vazhi Editorial","role":"Research & writing"}]');
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (8,'kyoto','Kyoto','Kansai','Japan','japan','City','story-kyoto.jpg','Japan''s imperial capital for over a thousand years, Kyoto holds some 1,600 Buddhist temples and 400 Shinto shrines — and in winter, when snow settles on the Yasaka pagoda, the old city returns to something like its twelfth century.','[{"body": ["Founded as Heian-kyō in 794, Kyoto was spared the bombing of the Pacific War and preserves the densest concentration of cultural treasures in Japan: Kinkaku-ji and Ginkaku-ji, the Zen gardens of Ryōan-ji and Daitoku-ji, the thousand torii of Fushimi Inari, and the preserved lanes of Higashiyama and Gion.", "Visit district by district, on foot, in the early morning. Winter strips the crowds and the colour, leaving rooflines, incense and silence."], "heading": "Overview"}]','[{"label":"Founded","value":"794 CE (Heian-kyō)"},{"label":"Known for","value":"Temples, shrines, geisha districts"},{"label":"UNESCO","value":"17 component sites, 1994"}]','["konya","brihadisvara","tatev"]','{"country":"ஜப்பான்","facts":[{"label":"நிறுவப்பட்டது","value":"கி.பி. 794 (ஹெயான்-கியோ)"},{"label":"புகழ்பெற்றது","value":"கோயில்கள், திருக்கோயில்கள், கெய்ஷா மாவட்டங்கள்"},{"label":"யுனெஸ்கோ","value":"17 அங்கத் தளங்கள், 1994"}],"name":"கியோட்டோ","region":"கன்சாய்","sections":[{"body":["கி.பி. 794-இல் ஹெயான்-கியோ என நிறுவப்பட்ட கியோட்டோ பசிபிக் போரின் குணமூட்டலிலிருந்து தப்பியது; ஜப்பானின் அடர்த்தியான பண்பாட்டுப் புதையல்களைக் காக்கிறது: கின்காகு-ஜி, கின்காகு-ஜி, ரியோன்-ஜி, தைத்தோகு-ஜியின் ஸென் தோட்டங்கள், ஃபுஷிமி இனாரியின் ஆயிரம் தொரிகள், ஹிகாஷியாமா, கியோனின் காக்கப்பட்ட சந்துகள்.","மாவட்டம் வாரியாக, நடந்து, அதிகாலையில் பார்வையிடுங்கள். குளிர்காலம் கூட்டத்தையும் நிறத்தையும் உதறிவிட்டு கூரைக் கோடுகள், தூபம், அமைதி ஆகியவற்றை மட்டும் விட்டுச் செல்கிறது."],"heading":"கண்ணோட்டம்"}],"summary":"ஆயிரம் ஆண்டுகளுக்கும் மேலாக ஜப்பானின் பேரரசுத் தலைநகராக இருந்த கியோட்டோவில் சுமார் 1,600 புத்தக் கோயில்களும் 400 ஷின்டோ திருக்கோயில்களும் உள்ளன — யசாகா பகோடாவின் மீது பனி படரும் குளிர்காலத்தில் பழைய நகரம் தன் பன்னிரண்டாம் நூற்றாண்டுக்கே திரும்புகிறது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Kyoto, Kyoto Prefecture, Japan',35.0116,135.7681,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (9,'konya','Konya','Central Anatolia','Turkey','turkey','City','story-konya.jpg','Capital of the Seljuk Sultanate of Rum and home of the poet-mystic Rumi, Konya is Turkey''s most spiritual city — its green-tiled Mevlana Museum the destination of a pilgrimage that has never quite stopped.','[{"body": ["As Iconium and then capital of the Seljuks, Konya gathered the finest stonework of 12th–13th century Anatolia: the Alaeddin Mosque, the Karatay and İnce Minare madrasas with their forests of carved portals.", "After the Mongol upheavals, the city became the home of Jalal al-Din Rumi and the Mevlevi order he inspired. His mausoleum, with its fluted turquoise dome, now houses the Mevlana Museum. In December the Şeb-i Arus ceremonies fill the city with the turning of the whirling dervishes."], "heading": "Overview"}]','[{"label":"Era","value":"Seljuk capital, 12th–13th c."},{"label":"Known for","value":"Mevlana Museum, whirling dervishes"},{"label":"Region","value":"Central Anatolia"}]','["kyoto","brihadisvara","tatev"]','{"country":"துருக்கி","facts":[{"label":"காலம்","value":"செல்யுக் தலைநகரம், 12–13-ஆம் நூற்றாண்டு"},{"label":"புகழ்பெற்றது","value":"மெவ்லானா அருங்காட்சியகம், சுழலும் தரவீஷ்கள்"},{"label":"பிராந்தியம்","value":"மத்திய அனடோலியா"}],"name":"கொன்யா","region":"மத்திய அனடோலியா","sections":[{"body":["ஐகோனியமாகவும் பின்னர் செல்யுக்குகளின் தலைநகராகவும் இருந்த கொன்யா, 12–13-ஆம் நூற்றாண்டு அனடோலியாவின் சிறந்த கல் வேலைகளைத் திரட்டியது: அலாயெத்தின் பள்ளிவாசல்; செதுக்கப்பட்ட நுழைவாயில்களின் காடுகளான கராத்தாய், இன்செ மினாரே மதரசாக்கள்.","மங்கோலியக் குழப்பங்களுக்குப் பின், ஜலால் அல்-தின் ரூமியும் அவர் நிறுவிய மெவ்லெவி சபையும் இந்நகரை இருப்பிடமாக்கினர். குழல்வடிவ பர்கீசு நிறக் குவிமாடமுள்ள அவரது கல்லறை இன்று மெவ்லானா அருங்காட்சியகமாக உள்ளது. டிசம்பரில் ஷெப்-இ அரூஸ் விழாக்கள் நகரைச் சுழலும் தரவீஷ்களின் சுழற்சியால் நிரப்புகின்றன."],"heading":"கண்ணோட்டம்"}],"summary":"ரூம் செல்யுக் சுல்தானத்தின் தலைநகரமும் கவிஞர்-துறவி ரூமியின் இருப்பிடமுமான கொன்யா துருக்கியின் மிக ஆன்மீக நகரம் — அதன் பச்சை ஓட்டுக் குவிமாடமுள்ள மெவ்லானா அருங்காட்சியகம் ஒருபோதும் நின்றதில்லை என்ற தீர்த்தயாத்திரையின் இலக்கு."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Konya, Central Anatolia, Türkiye',37.8746,32.4932,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (10,'tatev','Tatev Monastery','Syunik Province','Armenia','armenia','Heritage','dest-armenia.jpg','Perched on a basalt shelf above the 500-metre Vorotan gorge, the 9th-century Tatev Monastery was medieval Armenia''s greatest university — reached today by the Wings of Tatev, the world''s longest reversible aerial tramway.','[{"body": ["Founded in 895, Tatev housed a university, scriptorium and fortress-treasury at the edge of the Vorotan canyon. Its Cathedral of Saints Peter and Paul, the Church of Saint Gregory, and the strange swaying Gavazan pillar survive in striking completeness.", "The 5.7 km ropeway from Halidzor drops you at the walls in twelve minutes; arriving by the old road, watching the monastery appear and vanish in the folds of the gorge, is slower and better."], "heading": "Overview"}]','[{"label":"Founded","value":"895 CE"},{"label":"Access","value":"Wings of Tatev tramway, 5.7 km"},{"label":"Setting","value":"Vorotan gorge, Syunik"}]','["kyoto","brihadisvara","sigiriya"]','{"country":"ஆர்மீனியா","facts":[{"label":"நிறுவப்பட்டது","value":"கி.பி. 895"},{"label":"அணுகல்","value":"தாதெவின் இறக்கைகள் கேபிள்கார், 5.7 கி.மீ."},{"label":"அமைவு","value":"வொரோத்தான் பள்ளத்தாக்கு, சியூனிக்"}],"name":"தாதெவ் மடாலயம்","region":"சியூனிக் மாகாணம்","sections":[{"body":["கி.பி. 895-இல் நிறுவப்பட்ட தாதெவ், வொரோத்தான் பள்ளத்தாக்கின் விளிம்பில் பல்கலைக்கழகம், எழுத்தறை, கோட்டை-கருவூலம் ஆகியவற்றைக் கொண்டிருந்தது. புனித பீதுரு-பவுல் பேராலயம், புனித கிரகோரி தேவாலயம், அசையும் வினோத கவாசான் தூண் ஆகியவை வியக்கத்தக்க முழுமையுடன் உயிர்ந்துள்ளன.","ஹலிட்சோரிலிருந்து 5.7 கி.மீ. கேபிள்கார் பன்னிரண்டு நிமிடங்களில் உங்களை மதில்களில் இறக்கும்; பழைய சாலையில் வந்து, பள்ளத்தாக்கின் மடிப்புகளில் மடாலயம் தோன்றி மறைவதைப் பார்ப்பது மெதுவானது — மேலும் சிறந்தது."],"heading":"கண்ணோட்டம்"}],"summary":"500 மீட்டர் ஆழமான வொரோத்தான் பள்ளத்தாக்கின் மேல் பாசால்ட் மேட்டில் அமர்ந்திருக்கும் 9-ஆம் நூற்றாண்டுத் தாதெவ் மடாலயம் இடைக்கால ஆர்மீனியாவின் மாபெரும் பல்கலைக்கழகம் — இன்று உலகின் மிக நீளமான திரும்பிச்செல்லும் கேபிள்கார் \\"தாதெவின் இறக்கைகள்\\" மூலம் அடையலாம்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Tatev, Syunik Province, Armenia',39.3792,46.25,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (11,'sigiriya','Sigiriya','Central Province','Sri Lanka','srilanka','Heritage','dest-srilanka.jpg','The Lion Rock of Sigiriya — a 200-metre column of granite crowned by the palace of King Kashyapa — is Sri Lanka''s most dramatic site: moats, water gardens, cloud-maiden frescoes and a staircase that once entered through a lion''s mouth.','[{"body": ["In the late 5th century CE, Kashyapa I moved his capital to this rock and ringed it with some of the oldest landscaped gardens in the world. Halfway up, a sheltered pocket holds the famous frescoes of the Sigiriya maidens; the Mirror Wall beside them preserves visitors'' graffiti from the 8th to 10th centuries.", "Climb at opening time to beat both heat and crowds — the summit palace ruins and the 360-degree jungle horizon are the reward."], "heading": "Overview"}]','[{"label":"Built","value":"5th century CE"},{"label":"Builder","value":"King Kashyapa I"},{"label":"UNESCO","value":"World Heritage, 1982"}]','["tatev","brihadisvara","kyoto"]','{"country":"இலங்கை","facts":[{"label":"கட்டப்பட்டது","value":"கி.பி. 5-ஆம் நூற்றாண்டு"},{"label":"கட்டியவர்","value":"மன்னர் முதலாம் காசியப்பன்"},{"label":"யுனெஸ்கோ","value":"உலகப் பாரம்பரியம், 1982"}],"name":"சிகிரியா","region":"மத்திய மாகாணம்","sections":[{"body":["கி.பி. 5-ஆம் நூற்றாண்டின் இறுதியில், முதலாம் காசியப்பன் தலைநகரை இப்பாறைக்கு மாற்றி, உலகின் மிகப் பழமையான நில அமைப்புத் தோட்டங்களால் சுற்றினார். நடுவழியில், அடைப்புள்ள இடத்தில் புகழ்பெற்ற சிகிரியா மாதரின் சுவரோவியங்கள்; அருகிலுள்ள கண்ணாடிச் சுவர் 8–10-ஆம் நூற்றாண்டு வருவோரின் சுவரெழுத்துகளைக் காக்கிறது.","வெப்பத்தையும் கூட்டத்தையும் முந்திக் கொள்ள திறக்கும் நேரத்தில் ஏறுங்கள் — உச்சி அரண்மனை இடிபாடுகளும் 360-பாகைக் காட்டுக் கண்டிகையும் வெகுமதி."],"heading":"கண்ணோட்டம்"}],"summary":"சிகிரியாவின் சிங்கப்பாறை — மன்னர் காசியப்பனின் அரண்மனையைத் தலையில் சுமக்கும் 200 மீட்டர் பளிங்குத் தூண் — இலங்கையின் மிக வியப்பான தளம்: அகழிகள், நீர்த் தோட்டங்கள், மேகமாதர் ஓவியங்கள், ஒருகாலத்தில் சிங்க வாயில் வழியே நுழைந்த படிக்கட்டு."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Sigiriya, Central Province, Sri Lanka',7.957,80.7603,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (12,'bruges','Bruges','West Flanders','Belgium','europe','City','dest-europe.jpg','The best-preserved medieval city in Europe: Bruges turned its back on modernity when its river silted up in the 15th century, and the canals, belfry and stepped gables have kept its Gothic face almost photographically intact.','[{"body": ["As the northern hub of medieval trade, Bruges grew rich on wool and banking — the Bourse may be the world''s first stock exchange. When the Zwin channel silted, the city slept for four centuries, which is precisely why its street pattern, brick Gothic houses and canal ring survive.", "See it at blue hour from the Rozenhoedkaai, climb the 83-metre Belfry, then lose the crowds in the beguinage and the streets east of the canal ring."], "heading": "Overview"}]','[{"label":"Golden age","value":"12th–15th century"},{"label":"Known for","value":"Canals, Belfry, Gothic brickwork"},{"label":"UNESCO","value":"Historic centre, 2000"}]','["kyoto","konya","brihadisvara"]','{"country":"பெல்ஜியம்","facts":[{"label":"பொற்காலம்","value":"12–15-ஆம் நூற்றாண்டு"},{"label":"புகழ்பெற்றது","value":"கால்வாய்கள், மணிக்கோபுரம், கோதிக் செங்கல் வேலை"},{"label":"யுனெஸ்கோ","value":"வரலாற்று மையம், 2000"}],"name":"புரூஸ்","region":"மேற்கு ஃப்ளாண்டர்ஸ்","sections":[{"body":["இடைக்கால வாணிபத்தின் வடக்கு மையமாக, புரூஸ் கம்பளியிலும் வங்கித் துறையிலும் செழித்தது — போர்ஸ் உலகின் முதல் பங்குச் சந்தையாக இருக்கலாம். ஸ்வின் கால்வாய் மணலால் அடைக்கப்பட்டபோது நகரம் நான்கு நூற்றாண்டுகள் உறங்கியது — அதன் தெரு அமைப்பு, செங்கல் கோதிக் வீடுகள், கால்வாய் வளையம் உயிர்ந்ததற்கான காரணமே அதுவும்.","ரோசன்ஹூட்காயில் இருந்து நீல நேரத்தில் பாருங்கள்; 83 மீட்டர் மணிக்கோபுரத்தில் ஏறுங்கள்; பின்னர் பெகினாஜிலும் கால்வாய் வளையத்திற்குக் கிழக்கிலுள்ள தெருக்களிலும் கூட்டத்தை இழந்துவிடுங்கள்."],"heading":"கண்ணோட்டம்"}],"summary":"ஐரோப்பாவின் மிக நன்றாகக் காக்கப்பட்ட இடைக்கால நகரம்: 15-ஆம் நூற்றாண்டில் அதன் ஆறு மணலால் அடைபட்டபோது புரூஸ் நவீனத்திற்கு முதுகு காட்டியது; கால்வாய்கள், மணிக்கோபுரம், படிப்படியான முகப்புகள் ஆகியவை அதன் கோதிக் முகத்தைக் கிட்டத்தட்ட புகைப்படம் போல மாறாமல் வைத்துள்ளன."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Bruges, West Flanders, Belgium',51.2093,3.2247,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (13,'nara','Nara','Kansai','Japan','japan','Heritage','dest-japan.jpg','Japan''s first permanent capital (710–784), where Tōdai-ji''s Great Buddha Hall — among the largest wooden buildings on earth — shelters a 15-metre bronze Buddha, and sacred deer roam the park between the shrines.','[{"body": ["Japan''s first permanent capital (710–784), where Tōdai-ji''s Great Buddha Hall — among the largest wooden buildings on earth — shelters a 15-metre bronze Buddha, and sacred deer roam the park between the shrines."], "heading": "Overview"}]','[{"label":"Country","value":"Japan"},{"label":"Region","value":"Kansai"}]','["brihadisvara","kyoto","konya"]','{"country":"ஜப்பான்","name":"நாரா","region":"கன்சாய்","summary":"ஜப்பானின் முதல் நிரந்தரத் தலைநகர் (710–784); தோதை-ஜியின் மாபெரும் புத்தர் மண்டபம் — பூமியின் மிகப்பெரிய மரக் கட்டிடங்களில் ஒன்று — 15 மீட்டர் வெண்கலப் புத்தரைக் காக்கிறது; திருக்கோயில்களுக்கிடையே புனித மான்கள் பூங்காவில் உலவுகின்றன."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Nara, Nara Prefecture, Japan',34.6851,135.8048,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (14,'tokyo','Tokyo','Kantō','Japan','japan','City','dest-japan.jpg','From the incense of Sensō-ji in Asakusa to the forested calm of Meiji Shrine, Tokyo folds a 400-year pilgrimage city inside the world''s largest metropolis.','[{"body": ["From the incense of Sensō-ji in Asakusa to the forested calm of Meiji Shrine, Tokyo folds a 400-year pilgrimage city inside the world''s largest metropolis."], "heading": "Overview"}]','[{"label":"Country","value":"Japan"},{"label":"Region","value":"Kantō"}]','["brihadisvara","kyoto","konya"]','{"country":"ஜப்பான்","name":"டோக்கியோ","region":"காந்தோ","summary":"அசாகுசாவில் சென்சோ-ஜியின் தூபம் முதல் மெய்ஜி திருக்கோயிலின் காடுபோன்ற அமைதி வரை — உலகின் மிகப்பெரிய பெருநகருக்குள் டோக்கியோ 400-ஆண்டு தீர்த்தயாத்திரை நகரை மடித்து வைத்திருக்கிறது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Tokyo, Kantō, Japan',35.6762,139.6503,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (15,'fuji-five-lakes','Fuji Five Lakes','Yamanashi','Japan','japan','Nature','place-fuji.jpg','The five lakes at the northern foot of Mount Fuji — Kawaguchi, Yamanaka, Sai, Shōji and Motosu — hold the classic mirror views of the sacred mountain, best at dawn before the wind rises.','[{"body": ["The five lakes at the northern foot of Mount Fuji — Kawaguchi, Yamanaka, Sai, Shōji and Motosu — hold the classic mirror views of the sacred mountain, best at dawn before the wind rises."], "heading": "Overview"}]','[{"label":"Country","value":"Japan"},{"label":"Region","value":"Yamanashi"}]','["brihadisvara","kyoto","konya"]','{"country":"ஜப்பான்","name":"ஃபுஜி ஐந்து ஏரிகள்","region":"யமனாஷி","summary":"ஃபுஜி மலையின் வடக்கு அடிவாரத்திலுள்ள ஐந்து ஏரிகள் — கவாகுச்சி, யமனாகா, சாய், ஷோஜி, மொத்தோசு — புனித மலையின் கண்ணாடித் தோற்றங்களைக் கொடுக்கின்றன; காற்று எழுவதற்கு முன் விடியற்காலையில் மிகச் சிறந்தவை."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Fujikawaguchiko, Yamanashi, Japan',35.5053,138.7633,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (16,'hiroshima','Hiroshima','Chūgoku','Japan','japan','City','dest-japan.jpg','A city rebuilt as a monument to peace: the A-Bomb Dome, the Peace Memorial Park and Museum, and the island shrine of Itsukushima an hour down the bay.','[{"body": ["A city rebuilt as a monument to peace: the A-Bomb Dome, the Peace Memorial Park and Museum, and the island shrine of Itsukushima an hour down the bay."], "heading": "Overview"}]','[{"label":"Country","value":"Japan"},{"label":"Region","value":"Chūgoku"}]','["brihadisvara","kyoto","konya"]','{"country":"ஜப்பான்","name":"ஹிரோஷிமா","region":"சூகோகு","summary":"அமைதிக்கான நினைவுச்சின்னமாக மீண்டும் கட்டப்பட்ட நகரம்: அணுக்குண்டு குவிமாடம், அமைதி நினைவுப் பூங்காவும் அருங்காட்சியகமும், விரிகுடாவில் ஒரு மணி நேரத்தில் இத்சுகுஷிமா தீவுத் திருக்கோயில்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Hiroshima, Chūgoku, Japan',34.3853,132.4553,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (17,'istanbul','Istanbul','Marmara','Turkey','turkey','City','dest-turkey.jpg','Constantinople for sixteen centuries: Hagia Sophia, the Blue Mosque, Topkapı Palace and the Grand Bazaar layered where Europe meets Asia across the Bosphorus.','[{"body": ["Constantinople for sixteen centuries: Hagia Sophia, the Blue Mosque, Topkapı Palace and the Grand Bazaar layered where Europe meets Asia across the Bosphorus."], "heading": "Overview"}]','[{"label":"Country","value":"Turkey"},{"label":"Region","value":"Marmara"}]','["brihadisvara","kyoto","konya"]','{"country":"துருக்கி","name":"இசுதான்புல்","region":"மர்மரா","summary":"பதினாறு நூற்றாண்டுகள் கான்ஸ்டான்டினோப்பிள்: ஹாகியா சோஃபியா, நீலப் பள்ளிவாசல், தோப்காப்பி அரண்மனை, கிராண்ட் பஜார் — ஐரோப்பாவும் ஆசியாவும் பொஸ்போரசுக்கு இருபுறமும் சந்திக்கும் இடத்தில் அடுக்கடுக்காக."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Istanbul, Marmara, Türkiye',41.0082,28.9784,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (18,'cappadocia','Cappadocia','Central Anatolia','Turkey','turkey','Nature','dest-turkey.jpg','A volcanic moonscape of fairy chimneys honeycombed with Byzantine cave churches, and at dawn a sky full of balloons drifting over Göreme.','[{"body": ["A volcanic moonscape of fairy chimneys honeycombed with Byzantine cave churches, and at dawn a sky full of balloons drifting over Göreme."], "heading": "Overview"}]','[{"label":"Country","value":"Turkey"},{"label":"Region","value":"Central Anatolia"}]','["brihadisvara","kyoto","konya"]','{"country":"துருக்கி","name":"கப்படோக்கியா","region":"மத்திய அனடோலியா","summary":"பைசான்டிய குகைக் கோயில்கள் துளைத்தெழும் கனவுருவச் சுண்ணாம்புக் கூம்புகளின் எரிமலை நிலாநிலத்திடல்; விடியற்காலையில் கோரெமேவின் மீது பலூன்கள் நிறைந்த வானம்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Göreme, Nevşehir, Türkiye',38.6431,34.8289,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (19,'ephesus','Ephesus','Aegean','Turkey','turkey','Heritage','dest-turkey.jpg','The most complete Greco-Roman city in the Mediterranean: the Library of Celsus, the 25,000-seat theatre, and marble streets walked by emperors and apostles.','[{"body": ["The most complete Greco-Roman city in the Mediterranean: the Library of Celsus, the 25,000-seat theatre, and marble streets walked by emperors and apostles."], "heading": "Overview"}]','[{"label":"Country","value":"Turkey"},{"label":"Region","value":"Aegean"}]','["brihadisvara","kyoto","konya"]','{"country":"துருக்கி","name":"எஃபிசஸ்","region":"ஏஜியன்","summary":"மத்தியதரைக் கடலின் மிக முழுமையான கிரேக்க-ரோம நகரம்: செல்சஸ் நூலகம், 25,000 இருக்கை அரங்கம், பேரரசர்களும் தூதர்களும் நடந்த பளிங்குத் தெருக்கள்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Selçuk, İzmir, Türkiye',37.939,27.342,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (20,'yerevan','Yerevan','Ararat plain','Armenia','armenia','City','place-yerevan.jpg','One of the world''s oldest continuously inhabited cities (782 BCE), built of rose volcanic tuff, with Mount Ararat filling the horizon from the Cascade''s terraces.','[{"body": ["One of the world''s oldest continuously inhabited cities (782 BCE), built of rose volcanic tuff, with Mount Ararat filling the horizon from the Cascade''s terraces."], "heading": "Overview"}]','[{"label":"Country","value":"Armenia"},{"label":"Region","value":"Ararat plain"}]','["brihadisvara","kyoto","konya"]','{"country":"ஆர்மீனியா","name":"யெரெவான்","region":"அரராத் சமவெளி","summary":"உலகின் தொடர்ந்து குடியேற்றமுள்ள பழமையான நகரங்களில் ஒன்று (கி.மு. 782); ரோஜா நிற எரிமலைக் கல்லால் கட்டப்பட்டது; காஸ்கேடின் மேடைகளிலிருந்து அரராத் மலை கண்டிகையை நிரப்புகிறது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Yerevan, Armenia',40.1792,44.4991,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (21,'sevan','Lake Sevan','Gegharkunik','Armenia','armenia','Nature','dest-armenia.jpg','The blue eye of Armenia — a vast high-altitude lake whose peninsula monastery, Sevanavank, has watched the water since 874 CE.','[{"body": ["The blue eye of Armenia — a vast high-altitude lake whose peninsula monastery, Sevanavank, has watched the water since 874 CE."], "heading": "Overview"}]','[{"label":"Country","value":"Armenia"},{"label":"Region","value":"Gegharkunik"}]','["brihadisvara","kyoto","konya"]','{"country":"ஆர்மீனியா","name":"செவான் ஏரி","region":"கெகார்குனிக்","summary":"ஆர்மீனியாவின் நீலக் கண் — மலைமேட்டிலுள்ள பரந்த ஏரி; அதன் தீபகற்ப மடாலயம் செவானாவாங்க் கி.பி. 874 முதல் நீரைக் கண்டு நிற்கிறது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Lake Sevan, Gegharkunik, Armenia',40.3438,45.3267,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (22,'dilijan','Dilijan','Tavush','Armenia','armenia','Nature','dest-armenia.jpg','Forested spa town in the "Armenian Switzerland", gateway to the medieval monasteries of Haghartsin and Goshavank hidden in the beech woods.','[{"body": ["Forested spa town in the \\"Armenian Switzerland\\", gateway to the medieval monasteries of Haghartsin and Goshavank hidden in the beech woods."], "heading": "Overview"}]','[{"label":"Country","value":"Armenia"},{"label":"Region","value":"Tavush"}]','["brihadisvara","kyoto","konya"]','{"country":"ஆர்மீனியா","name":"திலிஜான்","region":"தாவுஷ்","summary":"\\"ஆர்மீனிய சுவிட்சர்லாந்து\\" எனப்படும் காடுபோன்ற மலைநகரம்; பீச் காடுகளில் மறைந்திருக்கும் இடைக்கால மடாலயங்கள் ஹகார்த்சின், கோஷாவாங்க் ஆகியவற்றின் நுழைவாயில்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Dilijan, Tavush, Armenia',40.7415,44.8632,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (23,'kandy','Kandy','Central Province','Sri Lanka','srilanka','City','dest-srilanka.jpg','The last royal capital of Sri Lanka, wrapped around a lake, guarding the Temple of the Sacred Tooth Relic — the island''s holiest shrine.','[{"body": ["The last royal capital of Sri Lanka, wrapped around a lake, guarding the Temple of the Sacred Tooth Relic — the island''s holiest shrine."], "heading": "Overview"}]','[{"label":"Country","value":"Sri Lanka"},{"label":"Region","value":"Central Province"}]','["brihadisvara","kyoto","konya"]','{"country":"இலங்கை","name":"கண்டி","region":"மத்திய மாகாணம்","summary":"இலங்கையின் கடைசி அரச தலைநகர்; ஏரியைச் சுற்றி அமைந்து, தீவின் மிகப் புனிதத் தலமான புனிதப் பல் பண்டைக் கோயிலைக் காவல் காக்கிறது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Kandy, Central Province, Sri Lanka',7.2906,80.6337,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (24,'anuradhapura','Anuradhapura','North Central','Sri Lanka','srilanka','Heritage','dest-srilanka.jpg','Capital of Sri Lanka for 1,300 years: colossal brick dagabas, the sacred Bodhi tree grown from the original at Bodh Gaya, and monastic ruins in the jungle.','[{"body": ["Capital of Sri Lanka for 1,300 years: colossal brick dagabas, the sacred Bodhi tree grown from the original at Bodh Gaya, and monastic ruins in the jungle."], "heading": "Overview"}]','[{"label":"Country","value":"Sri Lanka"},{"label":"Region","value":"North Central"}]','["brihadisvara","kyoto","konya"]','{"country":"இலங்கை","name":"அனுராதபுரம்","region":"வட மத்திய","summary":"1,300 ஆண்டுகள் இலங்கையின் தலைநகர்: பிரமாண்டச் செங்கல் தாகோபாக்கள், போத்கயாவிலுள்ள மூல மரத்திலிருந்து வளர்ந்த புனித போதி மரம், காட்டில் ஆசிரம இடிபாடுகள்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Anuradhapura, North Central Province, Sri Lanka',8.3114,80.4037,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (25,'ella','Ella','Uva Province','Sri Lanka','srilanka','Nature','dest-srilanka.jpg','A hill-country village above the tea estates, where the Nine Arches Bridge carries blue trains through the mist to Demodara.','[{"body": ["A hill-country village above the tea estates, where the Nine Arches Bridge carries blue trains through the mist to Demodara."], "heading": "Overview"}]','[{"label":"Country","value":"Sri Lanka"},{"label":"Region","value":"Uva Province"}]','["brihadisvara","kyoto","konya"]','{"country":"இலங்கை","name":"எல்ல","region":"ஊவா மாகாணம்","summary":"தேயிலைத் தோட்டங்களின் மேலுள்ள மலைநாட்டுக் கிராமம்; ஒன்பது வளைவுகள் பாலம் நீல இரயில்களைப் பனிமூட்டத்தில் தெமொதாராவுக்குக் கொண்டு செல்கிறது."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Ella, Uva Province, Sri Lanka',6.8767,81.0463,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (26,'rome','Rome','Lazio','Italy','europe','City','dest-europe.jpg','Twenty-eight centuries in one streetscape: the Colosseum and Forum, the Pantheon''s perfect dome, Bernini''s squares and the Vatican across the Tiber.','[{"body": ["Twenty-eight centuries in one streetscape: the Colosseum and Forum, the Pantheon''s perfect dome, Bernini''s squares and the Vatican across the Tiber."], "heading": "Overview"}]','[{"label":"Country","value":"Italy"},{"label":"Region","value":"Lazio"}]','["brihadisvara","kyoto","konya"]','{"country":"இத்தாலி","name":"ரோம்","region":"லாசியோ","summary":"ஒரே தெருவில் இருபத்தெட்டு நூற்றாண்டுகள்: கொலோசியமும் ஃபோரமும், பாந்தியனின் கச்சிதமான குவிமாடம், பெர்னினியின் சதுக்கங்கள், டைபருக்கு அப்பால் வாதிக்கன்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Rome, Lazio, Italy',41.9028,12.4964,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (27,'prague','Prague','Bohemia','Czechia','europe','City','dest-europe.jpg','The city of a hundred spires — Charles Bridge at dawn, the castle above the Vltava, and a Gothic old town that survived the twentieth century intact.','[{"body": ["The city of a hundred spires — Charles Bridge at dawn, the castle above the Vltava, and a Gothic old town that survived the twentieth century intact."], "heading": "Overview"}]','[{"label":"Country","value":"Czechia"},{"label":"Region","value":"Bohemia"}]','["brihadisvara","kyoto","konya"]','{"country":"செக்கியா","name":"பிராக்","region":"பொஹீமியா","summary":"நூறு கோபுரங்களின் நகரம் — விடியற்காலையில் சார்லஸ் பாலம், வில்தாவாவின் மேல் கோட்டை, இருபதாம் நூற்றாண்டை முழுமையாக உயிர்வாழ்ந்த கோதிக் பழைய நகரம்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Prague, Bohemia, Czechia',50.0755,14.4378,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (28,'granada','Granada','Andalusia','Spain','europe','City','dest-europe.jpg','The last emirate of Al-Andalus, crowned by the Alhambra — Nasrid palaces of carved stucco and courtyards of water beneath the Sierra Nevada.','[{"body": ["The last emirate of Al-Andalus, crowned by the Alhambra — Nasrid palaces of carved stucco and courtyards of water beneath the Sierra Nevada."], "heading": "Overview"}]','[{"label":"Country","value":"Spain"},{"label":"Region","value":"Andalusia"}]','["brihadisvara","kyoto","konya"]','{"country":"எசுப்பானியா","name":"கிரனாடா","region":"அந்தலூசியா","summary":"அல்-அந்தலூசின் கடைசி அமீரகம்; அல்ஹம்ப்ராவால் முடிசூட்டப்பட்டது — சியரா நெவாடாவின் கீழ் செதுக்கப்பட்ட சுதை நஸ்ரித் அரண்மனைகளும் நீர் முற்றங்களும்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Granada, Andalusia, Spain',37.1773,-3.5986,NULL);
INSERT INTO `place_articles` (`id`,`slug`,`name`,`region`,`country`,`destSlug`,`type`,`img`,`summary`,`sections`,`facts`,`related`,`ta`,`createdAt`,`updatedAt`,`status`,`publishedAt`,`address`,`lat`,`lng`,`contributors`) VALUES (29,'athens','Athens','Attica','Greece','europe','City','dest-europe.jpg','The Acropolis above a living city: the Parthenon, the Agora where democracy argued itself into being, and tavernas in the lanes of Plaka.','[{"body": ["The Acropolis above a living city: the Parthenon, the Agora where democracy argued itself into being, and tavernas in the lanes of Plaka."], "heading": "Overview"}]','[{"label":"Country","value":"Greece"},{"label":"Region","value":"Attica"}]','["brihadisvara","kyoto","konya"]','{"country":"கிரீஸ்","name":"ஏதன்ஸ்","region":"அட்டிகா","summary":"உயிரோட்டமுள்ள நகரின் மேல் அக்ரோபொலிஸ்: பார்த்தினன், ஜனநாயகம் தன்னை விவாதித்து உருவாக்கிக் கொண்ட அகோரா, பிளாகாவின் சந்துகளில் உணவகங்கள்."}','2026-08-13 00:30:07','2026-08-13 00:30:07','published',NULL,'Athens, Attica, Greece',37.9838,23.7275,NULL);
