TRUNCATE TABLE `markers`;
TRUNCATE TABLE `states`;
TRUNCATE TABLE `journeys`;
TRUNCATE TABLE `place_articles`;
TRUNCATE TABLE `stories`;
TRUNCATE TABLE `series`;
TRUNCATE TABLE `destinations`;
TRUNCATE TABLE `page_sections`;
TRUNCATE TABLE `settings`;
TRUNCATE TABLE `meta`;
TRUNCATE TABLE `fonts`;
TRUNCATE TABLE `media`;

SET FOREIGN_KEY_CHECKS=1;

